package com.taskmanagement.domain.ai;

import java.util.Objects;

/**
 * Proposed subtask generated by AI assistant.
 */
public record AiSubTaskProposal(String title, String explanation) {
    public AiSubTaskProposal {
        Objects.requireNonNull(title, "SubTask title cannot be null");
        String trimmed = title.trim();
        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException("SubTask title cannot be empty");
        }
        title = trimmed;
        explanation = explanation == null ? "" : explanation.trim();
    }

    public AiSubTaskProposal(String title) {
        this(title, "");
    }
}
